function validate([red, blue]) {
  if (!Number.isInteger(red) || red < 1 || red > 100) return 'red is an integer from 1 to 100.';
  if (!Number.isInteger(blue) || blue < 1 || blue > 100) return 'blue is an integer from 1 to 100.';
  return null;
}

