function maxHeightOfTriangle(red, blue) {
  let best = 0;
  for (const [top, other] of [[red, blue], [blue, red]]) {
    const balls = [top, other];
    let height = 0;
    while (balls[height % 2] >= height + 1) {
      balls[height % 2] -= height + 1;
      height++;
    }
    best = Math.max(best, height);
  }
  return best;
}

