function maxHeightOfTriangle(red, blue) {
  // Height h is possible when the odd rows fit in one colour and the even rows in the other.
  let best = 0;
  for (let h = 1; h <= 40; h++) {
    let oddRows = 0, evenRows = 0;
    for (let row = 1; row <= h; row++) {
      if (row % 2 === 1) oddRows += row;
      else evenRows += row;
    }
    if ((oddRows <= red && evenRows <= blue) || (oddRows <= blue && evenRows <= red)) best = h;
  }
  return best;
}

