function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') return [pick(60, 100), pick(60, 100)];
  const high = rand() < 0.5 ? 8 : 100;
  return [pick(1, high), pick(1, high)];
}
